using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection.Metadata;using System.Security.Cryptography;using System.Text.Json;
using var stream=File.OpenRead(args[0]);using var provider=MetadataReaderProvider.FromPortablePdbStream(stream);var r=provider.GetMetadataReader();var rows=new List<object>();int main=0;
foreach(var h in r.Documents){var d=r.GetDocument(h);string p=r.GetString(d.Name);var expected=r.GetBlobBytes(d.Hash);if(!File.Exists(p))throw new Exception("SOURCE_MISSING "+p);var bytes=File.ReadAllBytes(p);var actual=expected.Length==32?SHA256.HashData(bytes):SHA1.HashData(bytes);if(!actual.SequenceEqual(expected))throw new Exception("SOURCE_HASH_MISMATCH "+p);if(p.Contains("/Common/"))main++;rows.Add(new{Path=p,Hash=Convert.ToHexString(actual),Pass=true});}
if(main!=3)throw new Exception("COMMON_SOURCE_COUNT");Console.WriteLine(JsonSerializer.Serialize(new{Pass=true,Scope="Compiled portable PDB document checksums equal delivered source",Documents=rows},new JsonSerializerOptions{WriteIndented=true}));
